// ── Server→client requests ──
export interface ServerRequestMap {
  /** A dangerous command awaits the user's decision. */
  approval: { params: ApprovalRequestParams; result: ApprovalResult }
  /** The clarify tool: ask the user one question or a batch. */
  clarify: { params: ClarifyRequestParams; result: ClarifyResult }
  /** Click / type / scroll / annotate inside the in-app browser preview. */
  'preview.act': { params: PreviewActRequestParams; result: ValueResult }
  /** Read the in-app browser preview's text (JSON text answer). */
  'preview.read': { params: ReadRangeRequestParams; result: ValueResult }
  /** Masked value for a named env var (skills / setup flows). */
  secret: { params: SecretRequestParams; result: ValueResult }
  /** Masked sudo password for the terminal tool. */
  sudo: { params: SudoRequestParams; result: ValueResult }
  /** Read the visible in-app terminal buffer (JSON text answer). */
  'terminal.read': { params: ReadRangeRequestParams; result: ValueResult }
  /** Drive a guided tour highlight in the desktop renderer. */
  tour: { params: TourRequestParams; result: ValueResult }
  /** A one-time / 2FA code the user reads from their device. */
  'vault.code': { params: VaultCodeRequestParams; result: ValueResult }
  /** Save a login for a site the agent is about to fill; the answer is JSON {identifier, password}. */
  'vault.save_login': { params: VaultSaveLoginRequestParams; result: ValueResult }
  /** Master password to unlock an external password manager for this session. */
  'vault.unlock_prompt': { params: VaultUnlockRequestParams; result: ValueResult }
  /** Enumerate the native window below the app (JSON text answer). */
  'window.read': { params: EmptyRequestParams; result: ValueResult }
}
export type ServerRequestMethod = keyof ServerRequestMap
export const SERVER_REQUEST_METHODS = [
  'approval',
  'clarify',
  'preview.act',
  'preview.read',
  'secret',
  'sudo',
  'terminal.read',
  'tour',
  'vault.code',
  'vault.save_login',
  'vault.unlock_prompt',
  'window.read'
] as const satisfies readonly ServerRequestMethod[]

// ── Notifications (`event` frames) ──
export interface BackendGatewayEventMap {
  /** Output chunk from an agent-owned background process. */
  'agent.terminal.output': TerminalOutputPayload
  /** A /background side agent finished. */
  'background.complete': SideAgentCompletePayload
  /** Device-flow URL + code for the billing scope step-up; the client opens the browser. */
  'billing.step_up.verification': BillingStepUpVerificationPayload
  /** A bot-relay outbox envelope is queued; drain it. */
  'bot_relay.outbox.pending': ChangeSignalPayload
  /** Withdraw a pending controller command. */
  'browser.controller.cancel': BrowserControllerCancelPayload
  /** Dispatch one browser action to the attached controller. */
  'browser.controller.command': BrowserControllerCommandPayload
  /** Browser (CDP) connect / install progress line. */
  'browser.progress': BrowserProgressPayload
  /** A /btw side question was answered. */
  'btw.complete': SideAgentCompletePayload
  /** A connection operation opened on this session; the desktop renders its card. */
  'connection.request': ConnectionRequestPayload
  /** One transition or the settlement of an open connection operation. */
  'connection.update': ConnectionUpdatePayload
  /** cron/jobs.json moved; refetch the cron list. */
  'cron.changed': ChangeSignalPayload
  /** A session-level failure outside a turn (agent init, model switch, compression, resume). */
  error: ErrorPayload
  /** First frame of a connection: the resolved skin, the change-event capability and the replay epoch. */
  'gateway.ready': GatewayReadyPayload
  /** Apply a named desktop layout preset. */
  'layout.apply': LayoutApplyPayload
  /** The turn ended: final text, usage and outcome. */
  'message.complete': MessageCompletePayload
  /** One streamed chunk of the assistant reply. */
  'message.delta': StreamDeltaPayload
  /** Interim assistant commentary (text beside tool calls) sealed as its own segment. */
  'message.interim': MessageInterimPayload
  /** The agent reacted to a message; paint it live. */
  'message.reaction': MessageReactionPayload
  /** A turn began streaming; no payload. */
  'message.start': Record<string, never>
  /** A user correction accepted outside the attached TUI and rendered in its transcript. */
  'message.user': UserMessagePayload
  /** The MoA aggregator started. */
  'moa.aggregating': MoaAggregatingPayload
  /** MoA phase transition (currently only ``aggregator``). */
  'moa.phase': MoaPhasePayload
  /** MoA reference fan-out progress (n/total). */
  'moa.progress': MoaProgressPayload
  /** One MoA reference model's output. */
  'moa.reference': MoaReferencePayload
  /** Informational one-liner for the session (capabilities refreshed). */
  notice: NoticePayload
  /** Withdraw the notice with this key. */
  'notification.clear': NotificationClearPayload
  /** Show / replace a keyed out-of-band notice (toast or status bar). */
  'notification.show': NotificationShowPayload
  /** Pairing state moved; refetch pairing. */
  'pairing.changed': ChangeSignalPayload
  /** Focus / reveal a named desktop pane. */
  'pane.reveal': PaneRevealPayload
  /** The active pet / its spritesheet changed (watcher). */
  'pet.changed': PetChangedPayload
  /** Pet base-draft generation progress. */
  'pet.generate.progress': PetGenerateProgressPayload
  /** Pet hatch (row drawing) progress. */
  'pet.hatch.progress': PetHatchProgressPayload
  /** gateway_state.json moved; refetch platform status. */
  'platforms.changed': ChangeSignalPayload
  /** Close the preview pane or one tab. */
  'preview.close': PreviewClosePayload
  /** Open a URL / file in the desktop preview pane. */
  'preview.open': PreviewOpenPayload
  /** The hidden preview-restart agent finished. */
  'preview.restart.complete': SideAgentCompletePayload
  /** Progress line from the preview-restart agent. */
  'preview.restart.progress': PreviewRestartProgressPayload
  /** Affection reaction detected in the user's message (hearts etc.). */
  reaction: ReactionPayload
  /** A completed reasoning block (non-streaming providers). */
  'reasoning.available': StreamDeltaPayload
  /** One streamed chunk of the model's reasoning. */
  'reasoning.delta': StreamDeltaPayload
  /** The backend withdrew an open server→client request; clear the matching card only. */
  'request.cancel': RequestCancelPayload
  /** Background review of the last turn finished. */
  'review.summary': ReviewSummaryPayload
  /** Persisted goal / loop / heartbeat state changed. */
  'session.control.update': SessionControlUpdatePayload
  /** Live session settings snapshot (``server._session_info``); also the ``info`` of create/resume/activate. */
  'session.info': SessionLiveInfo
  /** The backend reclaimed a live session out from under its clients. */
  'session.reclaimed': SessionReclaimedPayload
  /** Deferred resume hydration progress. */
  'session.resume_progress': SessionResumeProgressPayload
  /** Auto-titling renamed the session (``session_id`` is the stored key). */
  'session.title': SessionTitlePayload
  /** Mid-turn usage tick; message.complete carries the authoritative final usage. */
  'session.usage': SessionUsagePayload
  /** state.db moved; refetch the session list. */
  'sessions.changed': ChangeSignalPayload
  /** The free-tier bootstrap finished (broadcast); the desktop's setup gate reads the record. */
  'setup.ready': SetupReadyPayload
  /** The active skin moved (name switch or live colour edit); repaint from this palette. */
  'skin.changed': SkinPayload
  /** Transient status line (kind: status, lifecycle, compacting, goal, loop, heartbeat, process, …). */
  'status.update': StatusUpdatePayload
  /** A child finished (status + observability rollup). */
  'subagent.complete': SubagentEventPayload
  /** Batched tool-name progress from a child. */
  'subagent.progress': SubagentEventPayload
  /** delegate_task accepted a child goal (before the child starts). */
  'subagent.spawn_requested': SubagentEventPayload
  /** A delegated child started running. */
  'subagent.start': SubagentEventPayload
  /** A child's reasoning chunk. */
  'subagent.thinking': SubagentEventPayload
  /** A child called a tool. */
  'subagent.tool': SubagentEventPayload
  /** An agent-owned background process closed. */
  'terminal.close': TerminalClosePayload
  /** Legacy thinking-text chunk (thinking_callback). */
  'thinking.delta': StreamDeltaPayload
  /** Point at a desktop element with a one-line tip bubble. */
  'tip.show': TipShowPayload
  /** Full todo snapshot after a todo tool ran. */
  'todo.updated': TodoUpdatedPayload
  /** A tool call finished: parsed result, summary, optional diff / todo snapshot. */
  'tool.complete': ToolCompletePayload
  /** The model is emitting a tool call's arguments. */
  'tool.generating': ToolGeneratingPayload
  /** Tool output was classified as risky (prompt-injection / secret findings). */
  'tool.output_risk': ToolOutputRiskPayload
  /** A tool call began (stable id + full args). */
  'tool.start': ToolStartPayload
  /** Barge-in: the spoken interjection interrupted the turn; no payload. */
  'voice.interrupted': Record<string, never>
  /** Voice recorder state changed. */
  'voice.status': VoiceStatusPayload
  /** A voice capture produced text (or a stop phrase / silence limit). */
  'voice.transcript': VoiceTranscriptPayload
  /** A wake phrase fired. */
  'wake.detected': WakeDetectedPayload
}
